}

.feature-visual-green {
  background: linear-gradient(135deg, #ECFDF5 0%, #d1fae5 100%);
  border-color: rgba(5,150,105,0.12);
}

.mock-ui {
  background: white;
  border-radius: var(--radius-lg);
  padding: var(--space-5);
