}

.mock-dot {
  display: flex;
  gap: 5px;
}
.mock-dot span {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--border);
}
.mock-dot span:nth-child(1) { background: #FF5F57; }
.mock-dot span:nth-child(2) { background: #FFBD2E; }
.mock-dot span:nth-child(3) { background: #28CA41; }

.mock-bar {
  height: 10px;
  border-radius: var(--radius-full);
