}
.success-message.show { display: block; }
.success-icon { color: var(--success); margin: 0 auto var(--space-4); display: block; }
.success-message h3 { font-size: 20px; font-weight: 700; color: var(--text-primary); margin-bottom: var(--space-2); }
.success-message p { font-size: 15px; color: var(--text-secondary); }

.contact-info-card {
  background: var(--surface);
  border-radius: var(--radius-xl);
  border: 1px solid var(--border);
  padding: var(--space-8);
}

.contact-info-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-4);
  padding: var(--space-5) 0;
  border-bottom: 1px solid var(--border-light);
}
.contact-info-item:last-child { border-bottom: none; }
.contact-info-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}
.contact-info-label { font-size: 12px; font-weight: 600; color: var(--text-muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 3px; }
.contact-info-value { font-size: 15px; color: var(--text-primary); font-weight: 500; }

.offices-list {
  margin-top: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}
.office-item {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-4);
  background: var(--bg);
  border-radius: var(--radius-md);
  font-size: 14px;
  color: var(--text-secondary);
}
.office-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--primary);
  flex-shrink: 0;
}

/* ========================
   ANIMATIONS
======================== */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes countUp {
  from { opacity: 0; transform: translateY(20px); }
  to   { opacity: 1; transform: translateY(0); }
}

.animate-in {
  animation: fadeIn 0.5s ease forwards;
}

.stat-item { opacity: 0; }
.stat-item.counted { animation: countUp 0.6s ease forwards; }

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ========================
   RESPONSIVE
======================== */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: 1 / -1; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); }
  .pricing-teaser-grid { grid-template-columns: 1fr; max-width: 420px; margin: 0 auto; }
  .pricing-card.featured { transform: scale(1); }
  .pricing-cards { grid-template-columns: 1fr; max-width: 440px; margin: 0 auto var(--space-16); }
  .pricing-card.featured { order: -1; }
  .feature-detail { grid-template-columns: 1fr; gap: var(--space-8); }
  .feature-detail.reverse { direction: ltr; }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .contact-layout { grid-template-columns: 1fr; }
  .integrations-grid { grid-template-columns: 1fr; }
}

@media (max-width: 768px) {
  :root { --space-20: 60px; --space-16: 48px; }
  .nav-links, .nav-actions .btn { display: none; }
  .hamburger { display: flex; }
  .hero { padding: 60px 0 50px; }
  .stats-grid { grid-template-columns: repeat(2, 1fr); gap: var(--space-6); }
  .steps-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .team-grid { grid-template-columns: repeat(2, 1fr); }
  .form-grid { grid-template-columns: 1fr; }
  .form-grid .form-group.full { grid-column: 1; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: var(--space-6); }
  .footer-brand { grid-column: 1 / -1; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .hero-actions { flex-direction: column; align-items: flex-start; }
  .cta-actions { flex-direction: column; align-items: center; }
  .testimonial-card { padding: var(--space-8) var(--space-6); }
}

@media (max-width: 480px) {
  .container { padding: 0 16px; }
  .stats-grid { grid-template-columns: 1fr 1fr; gap: var(--space-5); }
  .team-grid { grid-template-columns: 1fr 1fr; }
  .hero-title { font-size: 32px; }
}

